fn frame(t: i32) {
    host::display::clear(0x0d1014);
    let has: i32 = host::agent::viewer_has_identity();
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(0);
    host::display::state_set(0, down);
    let mut click: i32 = 0;
    if down == 1 && prev == 0 {
        click = 1;
    }

    if has == 0 {
        host::display::draw_string(110, 120, "THIS APP NEEDS", 0x8899aa, 2);
        host::display::draw_string(122, 150, "AN IDENTITY", 0x8899aa, 2);
        host::display::fill_rect(106, 220, 300, 90, 0xdddddd);
        host::display::draw_string(126, 252, "CREATE IDENTITY", 0x000000, 2);
        if click == 1 {
            let px: i32 = host::display::pointer_x();
            let py: i32 = host::display::pointer_y();
            if px >= 106 && px < 406 && py >= 220 && py < 310 {
                let got: i32 = host::agent::request_identity();
                if got == 1 {
                    host::display::state_set(1, 60);
                }
            }
        }
    } else {
        let welcome: i32 = host::display::state_get(1);
        if welcome > 0 {
            host::display::draw_string(160, 60, "WELCOME IN", 0x22bb44, 2);
            host::display::state_set(1, welcome - 1);
        }
        let subbed: i32 = host::agent::is_subscribed();
        let mut col: i32 = 0x222a33;
        if subbed == 1 {
            col = 0x1a5c2a;
        }
        host::display::fill_rect(106, 180, 300, 90, col);
        if subbed == 1 {
            host::display::draw_string(150, 212, "SUBSCRIBED", 0x99ffbb, 2);
        } else {
            host::display::draw_string(162, 212, "SUBSCRIBE", 0xffffff, 2);
        }
        host::display::draw_string(106, 320, "FEED MEMBERS", 0x556677, 1);
        host::display::draw_number(220, 314, host::agent::subscriber_count(), 0xffffff, 3);
        if click == 1 {
            let px2: i32 = host::display::pointer_x();
            let py2: i32 = host::display::pointer_y();
            if px2 >= 106 && px2 < 406 && py2 >= 180 && py2 < 270 {
                if subbed == 1 {
                    host::agent::unsubscribe();
                } else {
                    host::agent::subscribe();
                }
            }
        }
    }
    host::display::present();
}
